/**
 * Resolves the URL path, path parameters, and request name for a single HTTP route path.
 * Regex paths (Kong's `~` prefix) are translated via {@link generatePathPlaceholder}:
 * a cleanly-derived path becomes the request name, but when the regex can't be represented
 * literally the fallback keeps the original `~`-prefixed string as the name.
 */
function deriveHttpPathInfo(
  route: { name: string | null; id: string },
  routePath: string | null,
): { resolvedPath: string; pathParameters: { name: string; value: string }[]; baseName: string } {
  if (routePath === null) {
    return { resolvedPath: '', pathParameters: [], baseName: routeDisplayName(route) };
  }
  if (routePath.startsWith('~')) {
    const derived = generatePathPlaceholder(routePath.slice(1));
    const isFallback = derived.path === '/:path'
      && derived.pathParameters.length === 1
      && derived.pathParameters[0].name === 'path';
    return {
      resolvedPath: derived.path,
      pathParameters: derived.pathParameters,
      baseName: isFallback ? routePath : derived.path,
    };
  }
  return { resolvedPath: routePath, pathParameters: [], baseName: routePath };
